find=[];total=0
for x in rows:
 p=f"fresh-build/entries/{x['id']}/entry.v2.json";wp=f"fresh-build/entries/{x['id']}/evidence.draft.json";e=json.load(open(os.path.join(R,p)));cp=f"fresh-build/entries/{x['id']}/compile-report.json";cp=cp if os.path.exists(os.path.join(R,cp)) else f"fresh-build/entries/{x['id']}/evidence-compile-report.json";cr=json.load(open(os.path.join(R,cp)));assert cr['hardPass'];eh=h(p);wh=h(wp);assert eh==x['entrySha256'] and wh==x['worksheetSha256'];senses=e['Senses'];occ=sum(len(s.get('Occurrences',[])) for s in senses);anchors=sum(len(s.get('ClaimAnchors',[])) for s in senses);total+=occ+anchors;works={zc.work_id(o['RelPath']) for s in senses for o in s.get('Occurrences',[])}
 if x['ordinal'] in rev:v='REVISE';note=rev[x['ordinal']]
 else:v='KEEP';note=f'KEEP at this hash: {occ} exact occurrences across {len(works)} independent works, with {anchors} claim anchors. Full-case actor/action assignments are exact and attribution-clean; aliases remain within the preferred target, depth rows add distinct deployments without work-count padding, and #0g reveals no unrepresented incompatible referent.'
 find.append({'ordinal':x['ordinal'],'id':x['id'],'term':x['term'],'entrySha256':eh,'worksheetSha256':wh,'verdict':v,'finding':note,'senseCount':len(senses),'occurrenceCount':occ,'claimAnchorCount':anchors,'independentWorkCount':len(works)})
